<script setup>
import { computed, reactive, ref, watch } from 'vue'; import { Plus, Search, TrendingDown } from 'lucide-vue-next'; import { useAuthStore } from '@/stores/auth'; import { useFinanceStore } from '@/stores/finance'; import { useMasterDataStore } from '@/stores/masterData'; import { useUiStore } from '@/stores/ui'; import { formatCurrency, formatDate, todayIso } from '@/utils/formatters'; import BaseBadge from '@/components/ui/BaseBadge.vue'; import BaseButton from '@/components/ui/BaseButton.vue'; import BaseCard from '@/components/ui/BaseCard.vue'; import BaseInput from '@/components/ui/BaseInput.vue'; import BaseModal from '@/components/ui/BaseModal.vue'; import BaseSelect from '@/components/ui/BaseSelect.vue'; import BaseTextarea from '@/components/ui/BaseTextarea.vue'; import Pagination from '@/components/ui/Pagination.vue';
const finance=useFinanceStore(),auth=useAuthStore(),ui=useUiStore(),master=useMasterDataStore(),search=ref(''),vendorFilter=ref('semua'),categoryFilter=ref('semua'),page=ref(1),modal=ref(false),edit=ref(null),error=ref(''),pageSize=5; const accounts=computed(()=>master.activeRecordsFor('account')),vendors=computed(()=>master.activeRecordsFor('vendor')); const blank=()=>({date:todayIso(),vendorId:'',category:'',description:'',amount:'',transactionType:'cash',sourceAccountId:'',destinationAccount:null,referenceNumber:'',proofName:'',notes:''}); const form=reactive(blank()),readOnly=computed(()=>auth.role==='manager'); const vendor=id=>vendors.value.find(x=>x.id===id),account=id=>accounts.value.find(x=>x.id===id),typeLabel={cash:'Cash',qris:'QRIS',credit:'Credit',transfer:'Transfer'}; const filtered=computed(()=>finance.expenses.filter(x=>`${vendor(x.vendorId)?.nama||''} ${x.description}`.toLowerCase().includes(search.value.toLowerCase())&&(vendorFilter.value==='semua'||x.vendorId===vendorFilter.value)&&(categoryFilter.value==='semua'||x.category===categoryFilter.value))); const rows=computed(()=>filtered.value.slice((page.value-1)*pageSize,page.value*pageSize)),total=computed(()=>filtered.value.reduce((sum,x)=>sum+x.amount,0)); watch([search,vendorFilter,categoryFilter],()=>page.value=1);watch(()=>form.transactionType,type=>{if(type!=='transfer')form.destinationAccount=null}); const openAdd=()=>{edit.value=null;Object.assign(form,blank());error.value='';modal.value=true}; const openEdit=item=>{edit.value=item;Object.assign(form,item,{amount:String(item.amount)});error.value='';modal.value=true}; const save=()=>{try{edit.value?finance.updateExpense(edit.value.id,form):finance.addExpense(form);ui.notify(edit.value?'Pengeluaran berhasil diperbarui.':'Pengeluaran berhasil ditambahkan.');modal.value=false}catch(e){error.value=e.message}};
</script>
<template><div class="p-6"><header class="mb-5 flex justify-between"><div><h1 class="text-xl font-semibold text-[#172033]">Pengeluaran</h1><p class="mt-0.5 text-sm text-[#667085]">Pencatatan seluruh pengeluaran dan biaya operasional perusahaan.</p></div><BaseButton v-if="!readOnly" @click="openAdd"><Plus :size="15"/>Tambah Pengeluaran</BaseButton></header><BaseCard class="mb-5 flex justify-between" padding="p-4"><div><p class="text-xs text-[#667085]">Total Pengeluaran</p><p class="text-2xl font-bold text-[#DC2626]">{{formatCurrency(total)}}</p></div><TrendingDown :size="32" class="text-red-200"/></BaseCard><div class="mb-4 flex flex-wrap gap-3"><BaseInput v-model="search" class="max-w-xs flex-1" placeholder="Cari pengeluaran..."><template #prefix><Search :size="14"/></template></BaseInput><BaseSelect v-model="vendorFilter" class="w-44" :options="[{value:'semua',label:'Semua Vendor'},...vendors.map(x=>({value:x.id,label:x.nama}))]"/><BaseSelect v-model="categoryFilter" class="w-40" :options="[{value:'semua',label:'Semua Kategori'},'Infrastruktur','Peralatan','Operasional','Marketing']"/></div><section class="overflow-x-auto rounded-lg border border-[#E2E6EC] bg-white"><table class="w-full min-w-[1000px]"><thead><tr class="border-b bg-[#F9FAFB]"><th v-for="h in ['Tanggal','Vendor','Kategori','Keterangan','Jenis','Sumber','Tujuan','Nominal','Aksi']" :key="h" class="px-4 py-3 text-left text-xs text-[#667085]">{{h}}</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id" class="border-b"><td class="px-4 py-3 text-sm">{{formatDate(item.date)}}</td><td class="px-4 py-3 text-sm">{{vendor(item.vendorId)?.nama||'-'}}</td><td class="px-4 py-3"><BaseBadge variant="default">{{item.category}}</BaseBadge></td><td class="px-4 py-3 text-sm">{{item.description}}</td><td class="px-4 py-3 text-sm">{{typeLabel[item.transactionType]}}</td><td class="px-4 py-3 text-sm">{{account(item.sourceAccountId)?.nama||'-'}}</td><td class="px-4 py-3 text-sm">{{item.destinationAccount||'-'}}</td><td class="px-4 py-3 text-right text-sm font-semibold text-red-600">{{formatCurrency(item.amount)}}</td><td class="px-4 py-3"><button v-if="!readOnly" class="text-xs text-[#315DA8]" @click="openEdit(item)">Edit</button></td></tr></tbody></table><Pagination :page="page" :total="filtered.length" :per-page="pageSize" @change="page=$event"/></section><BaseModal :open="modal" :title="edit?'Edit Pengeluaran':'Tambah Pengeluaran'" size="wide" @close="modal=false"><div class="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-3"><BaseInput v-model="form.date" label="Tanggal" type="date" required/><BaseInput v-model="form.amount" label="Nominal (Rp)" type="number" required/><BaseSelect v-model="form.vendorId" label="Vendor" :options="[{value:'',label:'- Tanpa Vendor -'},...vendors.map(x=>({value:x.id,label:x.nama}))]"/><BaseSelect v-model="form.category" label="Kategori" required :options="[{value:'',label:'Pilih kategori'},'Infrastruktur','Peralatan','Operasional','Marketing']"/><BaseSelect v-model="form.transactionType" label="Jenis Transaksi" required :options="[{value:'cash',label:'Cash'},{value:'qris',label:'QRIS'},{value:'credit',label:'Credit'},{value:'transfer',label:'Transfer'}]"/><BaseSelect v-model="form.sourceAccountId" label="Rekening Sumber" required :options="[{value:'',label:'Pilih rekening sumber'},...accounts.map(x=>({value:x.id,label:x.nama}))]"/><BaseInput v-if="form.transactionType==='transfer'" v-model="form.destinationAccount" label="Rekening Tujuan" required placeholder="Bank / rekening tujuan"/><BaseInput v-model="form.referenceNumber" label="Nomor Referensi" placeholder="Opsional"/><div class="xl:col-span-1"><label class="mb-1.5 block text-sm font-medium text-[#172033]">Bukti Transaksi</label><input type="file" class="block w-full text-sm" @change="form.proofName=$event.target.files?.[0]?.name||''"/></div><BaseTextarea v-model="form.description" class="md:col-span-2 xl:col-span-3" label="Keterangan" required :rows="3"/><BaseTextarea v-model="form.notes" class="md:col-span-2 xl:col-span-3" label="Catatan" :rows="3"/></div><p v-if="error" class="mt-3 text-sm text-red-600">{{error}}</p><template #footer><BaseButton variant="secondary" @click="modal=false">Batal</BaseButton><BaseButton @click="save">Simpan</BaseButton></template></BaseModal></div></template>
